def _iter_evidence_files(
    repo: Path,
    roots: Iterable[str],
    *,
    evidence_kind: str,
) -> list[Path]:
    result: list[Path] = []

    for configured_root in roots:
        candidate = repo / configured_root
        if not candidate.exists():
            continue

        if candidate.is_file():
            candidates = [candidate]
        else:
            candidates = sorted(candidate.rglob("*"))

        for path in candidates:
            if not path.is_file():
                continue
            if path.suffix.lower() not in EVIDENCE_EXTENSIONS:
                continue
            if any(part in {".git", "__pycache__", "migrations"} for part in path.parts):
                continue

            if evidence_kind == "test" and not _looks_like_test_file(path):
                continue

            result.append(path)

            if len(result) >= 5000:
                return result

    return result

def _evidence_bucket(record: JsonDict) -> str:
    has_test = bool(record["supporting_test_files"])
    has_doc = bool(record["supporting_doc_files"])

    if has_test and has_doc:
        return "TEST_AND_DOC"
    if has_test:
        return "TEST_ONLY"
    if has_doc:
        return "DOC_ONLY"
    return "NONE"

def _local_contract_evidence(
    traces: list[JsonDict],
) -> list[JsonDict]:

    records: list[JsonDict] = []

    for trace_item in traces:
        for step in _terminal_steps(trace_item):
            if str(step.get("step_kind")) not in LOCAL_TERMINALS:
                continue

            records.append(
                {
                    "candidate_id": str(trace_item["candidate_id"]),
                    "source_id": str(trace_item["source_id"]),
                    "primitive": str(trace_item["primitive"]),
                    "terminal_kind": str(step["step_kind"]),
                    "file": step.get("file"),
                    "file_sha256": (step.get("file_sha256") or step.get("source_file_sha256")),
                    "line": step.get("line"),
                    "source": step.get("source"),
                    "semantic_type": "UNRESOLVED",
                    "semantic_contract_status": "MISSING",
                    "resolution_status": "UNRESOLVED",
                    "certification_claim": False,
                }
            )

    return records

def _manifest_evidence(
    source_root: Path,
    package_root: str,
) -> list[JsonDict]:

    variants = {
        package_root.lower(),
        package_root.lower().replace(
            "_",
            "-",
        ),
        package_root.lower().replace(
            "-",
            "_",
        ),
    }

    manifest_names = {
        "pyproject.toml",
        "setup.py",
        "setup.cfg",
        "requirements.txt",
        "requirements-dev.txt",
        "requirements_dev.txt",
        "Pipfile",
        "Pipfile.lock",
        "poetry.lock",
        "uv.lock",
    }

    evidence: list[JsonDict] = []

    for path in source_root.rglob("*"):
        if not path.is_file():
            continue

        if not (
            path.name in manifest_names
            or (path.name.startswith("requirements") and path.suffix == ".txt")
        ):
            continue

        text = path.read_text(
            encoding="utf-8",
            errors="replace",
        )

        for (
            line_number,
            line,
        ) in enumerate(
            text.splitlines(),
            start=1,
        ):
            lowered = line.lower()

            if not any(variant in lowered for variant in variants):
                continue

            stripped = line.strip()

            evidence.append(
                {
                    "file": str(path.relative_to(source_root)).replace(
                        "\\",
                        "/",
                    ),
                    "line": line_number,
                    "text": stripped,
                    "exact_pin_detected": ("==" in stripped),
                }
            )

    return evidence

def _module_import_evidence(
    tree: ast.Module,
    primitive: str,
) -> list[JsonDict]:

    evidence: list[JsonDict] = []

    for node in tree.body:
        if isinstance(
            node,
            ast.ImportFrom,
        ):
            module_name = node.module or ""

            for alias in node.names:
                if alias.name == "*":
                    evidence.append(
                        {
                            "evidence_kind": "WILDCARD_IMPORT",
                            "module": module_name,
                            "line": int(node.lineno),
                            "source": ast.unparse(node),
                        }
                    )

                    continue

                local_name = alias.asname or alias.name

                if local_name == primitive:
                    evidence.append(
                        {
                            "evidence_kind": "EXPLICIT_IMPORT",
                            "module": module_name,
                            "imported_name": alias.name,
                            "local_name": local_name,
                            "line": int(node.lineno),
                            "source": ast.unparse(node),
                        }
                    )

        elif isinstance(
            node,
            ast.Import,
        ):
            for alias in node.names:
                local_name = alias.asname or alias.name.split(".")[0]

                if local_name == primitive:
                    evidence.append(
                        {
                            "evidence_kind": "MODULE_IMPORT",
                            "module": alias.name,
                            "local_name": local_name,
                            "line": int(node.lineno),
                            "source": ast.unparse(node),
                        }
                    )

    return evidence

def _module_definition_evidence(
    tree: ast.Module,
    primitive: str,
) -> list[JsonDict]:

    evidence: list[JsonDict] = []

    for node in tree.body:
        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
            ),
        ):
            if node.name == primitive:
                evidence.append(
                    {
                        "evidence_kind": "MODULE_DEFINITION",
                        "definition_type": type(node).__name__,
                        "line": int(node.lineno),
                        "source": ast.unparse(node).splitlines()[0],
                    }
                )

        elif isinstance(
            node,
            ast.Assign,
        ):
            names = [
                target.id
                for target in node.targets
                if isinstance(
                    target,
                    ast.Name,
                )
            ]

            if primitive in names:
                evidence.append(
                    {
                        "evidence_kind": "MODULE_ASSIGNMENT",
                        "line": int(node.lineno),
                        "source": ast.unparse(node),
                    }
                )

        elif isinstance(
            node,
            ast.AnnAssign,
        ):
            if (
                isinstance(
                    node.target,
                    ast.Name,
                )
                and node.target.id == primitive
            ):
                evidence.append(
                    {
                        "evidence_kind": "MODULE_ASSIGNMENT",
                        "line": int(node.lineno),
                        "source": ast.unparse(node),
                    }
                )

    return evidence

def _occurrence_evidence(
    *,
    obligation: JsonDict,
    skeleton: JsonDict,
    source_tree: ast.Module,
) -> JsonDict:

    primitive = str(obligation["primitive"])

    kind = str(obligation["kind"])

    expression = str(obligation["source_expression"])

    parameters = {str(value) for value in skeleton["function_parameters"]}

    evidence: list[JsonDict] = []

    if kind == "CALL":
        callable_name, call_form = _callable_root(expression)

        if callable_name is not None and callable_name in parameters:
            evidence.append(
                {
                    "evidence_kind": "FUNCTION_PARAMETER_CALLABLE",
                    "parameter": callable_name,
                    "call_form": call_form,
                }
            )

        evidence.extend(
            _module_definition_evidence(
                source_tree,
                primitive,
            )
        )

        evidence.extend(
            _module_import_evidence(
                source_tree,
                primitive,
            )
        )

        if primitive in dir(builtins):
            evidence.append(
                {
                    "evidence_kind": "PYTHON_BUILTIN",
                    "primitive": primitive,
                }
            )

    elif kind == "GLOBAL_NAME":
        if primitive in parameters:
            evidence.append(
                {
                    "evidence_kind": "FUNCTION_PARAMETER_VALUE",
                    "parameter": primitive,
                }
            )

        evidence.extend(
            _module_definition_evidence(
                source_tree,
                primitive,
            )
        )

        evidence.extend(
            _module_import_evidence(
                source_tree,
                primitive,
            )
        )

    elif kind == "ATTRIBUTE":
        root = _attribute_root(expression)

        if root is not None and root in parameters:
            evidence.append(
                {
                    "evidence_kind": "PARAMETER_ATTRIBUTE_ACCESS",
                    "parameter": root,
                    "attribute": primitive,
                }
            )

        elif root is not None:
            evidence.append(
                {
                    "evidence_kind": "ATTRIBUTE_ROOT_CONTEXT",
                    "root": root,
                    "attribute": primitive,
                }
            )

    strong_kinds = {
        "FUNCTION_PARAMETER_CALLABLE",
        "FUNCTION_PARAMETER_VALUE",
        "EXPLICIT_IMPORT",
        "MODULE_IMPORT",
        "MODULE_DEFINITION",
        "MODULE_ASSIGNMENT",
        "PYTHON_BUILTIN",
    }

    if any(str(item["evidence_kind"]) in strong_kinds for item in evidence):
        status = "SOURCE_EVIDENCE_IDENTIFIED"

    elif any(str(item["evidence_kind"]) == "WILDCARD_IMPORT" for item in evidence):
        status = "SOURCE_EVIDENCE_PARTIAL"

    elif evidence:
        status = "CONTEXT_EVIDENCE_ONLY"

    else:
        status = "NO_SOURCE_EVIDENCE"

    return {
        "binding_id": str(obligation["binding_id"]),
        "kind": kind,
        "primitive": primitive,
        "family_class": str(obligation["family_class"]),
        "source_expression": expression,
        "context_inferred_type": str(obligation["inferred_type"]),
        "context_type_requirements": obligation["type_requirements"],
        "semantic_contract_required": (
            str(obligation["family_class"]) in SEMANTIC_CONTRACT_CLASSES
        ),
        "semantic_type": "UNRESOLVED",
        "semantic_definition_status": "UNRESOLVED",
        "evidence_status": status,
        "evidence": evidence,
    }

def replay_counterexample(
    contract: BusinessContract,
    inputs: dict[str, Any],
) -> ReplayResult:
    try:
        if not evaluate_boolean_expression(contract.precondition, inputs):
            return ReplayResult(
                valid=False,
                reason_code="replay_precondition_false",
                reason="symbolic counterexample does not satisfy the concrete precondition",
            )

        target = load_function(contract.target.source, contract.target.function)
        observed_result = target(**inputs)

        post_values = dict(inputs)
        post_values["result"] = observed_result
        postcondition_satisfied = evaluate_boolean_expression(
            contract.postcondition,
            post_values,
        )

        if postcondition_satisfied:
            return ReplayResult(
                valid=False,
                observed_result=observed_result,
                postcondition_satisfied=True,
                reason_code="replay_postcondition_true",
                reason="symbolic counterexample does not violate the concrete postcondition",
            )

        return ReplayResult(
            valid=True,
            observed_result=observed_result,
            postcondition_satisfied=False,
        )
    except TargetLoadError as exc:
        return ReplayResult(
            valid=False,
            reason_code="replay_target_load_error",
            reason=str(exc),
        )
    except ExpressionError as exc:
        return ReplayResult(
            valid=False,
            reason_code="replay_expression_error",
            reason=str(exc),
        )
    except Exception as exc:
        return ReplayResult(
            valid=False,
            reason_code="replay_target_execution_error",
            reason=f"target raised {type(exc).__name__}: {exc}",
        )

def _prove_equivalence(
    external: Z3Expr,
    candidate: Z3Expr,
    constraints: list[Z3Expr],
    inputs: JsonDict,
    symbols: dict[str, Z3Expr],
) -> JsonDict:
    solver = z3.Solver()

    if constraints:
        solver.add(*constraints)

    solver.add(external != candidate)

    started = time.perf_counter()
    status = solver.check()
    elapsed = time.perf_counter() - started

    if status == z3.unsat:
        return {
            "verdict": "PROVED",
            "solver_status": "unsat",
            "counterexample": None,
            "runtime_seconds": elapsed,
        }

    if status == z3.sat:
        return {
            "verdict": "DISPROVED",
            "solver_status": "sat",
            "counterexample": _model_to_json(
                solver.model(),
                inputs,
                symbols,
            ),
            "runtime_seconds": elapsed,
        }

    return {
        "verdict": "UNKNOWN",
        "solver_status": "unknown",
        "counterexample": None,
        "runtime_seconds": elapsed,
        "reason": solver.reason_unknown(),
    }

def verify_with_z3(
    contract: BusinessContract,
    *,
    timeout_ms: int = 10_000,
) -> Evidence:
    started = time.perf_counter()
    symbols = {spec.name: _symbol(spec) for spec in contract.inputs}

    try:
        compiler = Z3ExpressionCompiler(symbols)
        precondition = compiler.compile_boolean_text(contract.precondition)
        domain_constraints = _domain_constraints(contract, symbols)

        pre_result, pre_reason = _check_precondition_satisfiable(
            domain_constraints,
            precondition,
            timeout_ms,
        )
        if pre_result == z3.unsat:
            return _unknown(
                contract,
                started,
                reason_code="unsatisfiable_precondition",
                reason="precondition admits no values in the declared input domain",
                timeout_ms=timeout_ms,
            )
        if pre_result == z3.unknown:
            return _unknown(
                contract,
                started,
                reason_code="precondition_solver_unknown",
                reason=f"solver returned unknown: {pre_reason}",
                timeout_ms=timeout_ms,
            )

        analyzer = PythonSymbolicAnalyzer(contract.target.source, contract.target.function)
        paths = analyzer.extract_paths(symbols)

        coverage_result, coverage_model, coverage_reason = _check_path_coverage(
            domain_constraints,
            precondition,
            paths,
            timeout_ms,
        )
        if coverage_result == z3.sat:
            witness = (
                {
                    spec.name: _model_value(coverage_model, symbols[spec.name])
                    for spec in contract.inputs
                }
                if coverage_model is not None
                else None
            )
            return _unknown(
                contract,
                started,
                reason_code="incomplete_symbolic_path_coverage",
                reason="symbolic paths do not cover the entire admissible business domain",
                timeout_ms=timeout_ms,
                extra_metadata={"coverage_witness": witness},
            )
        if coverage_result == z3.unknown:
            return _unknown(
                contract,
                started,
                reason_code="path_coverage_solver_unknown",
                reason=f"solver returned unknown while checking path coverage: {coverage_reason}",
                timeout_ms=timeout_ms,
            )

        for index, path in enumerate(paths):
            post_symbols = dict(symbols)
            post_symbols["result"] = path.result
            postcondition = Z3ExpressionCompiler(post_symbols).compile_boolean_text(
                contract.postcondition
            )

            solver = z3.Solver()
            solver.set(timeout=timeout_ms)
            solver.add(*domain_constraints)
            solver.add(precondition)
            solver.add(path.condition)
            solver.add(z3.Not(postcondition))

            result = solver.check()

            if result == z3.sat:
                model = solver.model()
                counterexample = {
                    spec.name: _model_value(model, symbols[spec.name]) for spec in contract.inputs
                }
                symbolic_observed = _model_value(model, path.result)
                replay = replay_counterexample(contract, counterexample)

                if not replay.valid:
                    return _unknown(
                        contract,
                        started,
                        reason_code=replay.reason_code or "counterexample_replay_failed",
                        reason=replay.reason or "counterexample replay failed",
                        timeout_ms=timeout_ms,
                        extra_metadata={
                            "path_index": index,
                            "path_count": len(paths),
                            "candidate_counterexample": counterexample,
                            "symbolic_observed_result": symbolic_observed,
                            "concrete_observed_result": replay.observed_result,
                        },
                    )

                if replay.observed_result != symbolic_observed:
                    return _unknown(
                        contract,
                        started,
                        reason_code="symbolic_concrete_result_mismatch",
                        reason="symbolic and concrete execution produced different results",
                        timeout_ms=timeout_ms,
                        extra_metadata={
                            "path_index": index,
                            "path_count": len(paths),
                            "candidate_counterexample": counterexample,
                            "symbolic_observed_result": symbolic_observed,
                            "concrete_observed_result": replay.observed_result,
                        },
                    )

                return Evidence(
                    verdict=Verdict.DISPROVED,
                    contract_id=contract.contract_id,
                    backend="z3",
                    counterexample=counterexample,
                    observed_result=replay.observed_result,
                    postcondition_satisfied=False,
                    replay_validated=True,
                    metadata={
                        "path_index": index,
                        "path_count": len(paths),
                        "runtime_seconds": time.perf_counter() - started,
                        "timeout_ms": timeout_ms,
                        "z3_version": z3.get_version_string(),
                    },
                )

            if result == z3.unknown:
                return _unknown(
                    contract,
                    started,
                    reason_code="verification_solver_unknown",
                    reason=f"solver returned unknown: {solver.reason_unknown()}",
                    timeout_ms=timeout_ms,
                    extra_metadata={
                        "path_index": index,
                        "path_count": len(paths),
                    },
                )

    except (ExpressionError, UnsupportedProgram, ValueError, z3.Z3Exception) as exc:
        return _unknown(
            contract,
            started,
            reason_code="unsupported_or_invalid_semantics",
            reason=str(exc),
            timeout_ms=timeout_ms,
        )
    except (OSError, SyntaxError) as exc:
        return _unknown(
            contract,
            started,
            reason_code="target_source_error",
            reason=str(exc),
            timeout_ms=timeout_ms,
        )

    return Evidence(
        verdict=Verdict.PROVED,
        contract_id=contract.contract_id,
        backend="z3",
        metadata={
            "path_count": len(paths),
            "runtime_seconds": time.perf_counter() - started,
            "timeout_ms": timeout_ms,
            "z3_version": z3.get_version_string(),
        },
    )
